import assert from 'node:assert/strict';
import { canShip } from '../src/deploy.js';

describe('canShip', () => {
  it('allows deploys during business hours on weekdays', () => {
    // Tuesday at 10 AM
    const tue10am = new Date('2026-11-17T10:00:00Z');
    assert.equal(canShip(tue10am), true);

    // Wednesday at 2 PM
    const wed2pm = new Date('2026-11-18T14:00:00Z');
    assert.equal(canShip(wed2pm), true);

    // Thursday at 5 PM (before 6 PM cutoff)
    const thu5pm = new Date('2026-11-19T17:00:00Z');
    assert.equal(canShip(thu5pm), true);
  });

  it('blocks deploys on weekends', () => {
    // Saturday at noon
    const satNoon = new Date('2026-11-21T12:00:00Z');
    assert.equal(canShip(satNoon), false);

    // Sunday at 2 PM
    const sun2pm = new Date('2026-11-22T14:00:00Z');
    assert.equal(canShip(sun2pm), false);
  });

  it('blocks deploys on Friday after 3 PM', () => {
    // Friday at 2:59 PM - should allow
    const fri259pm = new Date('2026-11-20T14:59:00Z');
    assert.equal(canShip(fri259pm), true);

    // Friday at 3 PM - should block
    const fri3pm = new Date('2026-11-20T15:00:00Z');
    assert.equal(canShip(fri3pm), false);

    // Friday at 5 PM - should block
    const fri5pm = new Date('2026-11-20T17:00:00Z');
    assert.equal(canShip(fri5pm), false);
  });

  it('blocks deploys before 9 AM', () => {
    // Monday at 8:59 AM
    const mon859am = new Date('2026-11-23T08:59:00Z');
    assert.equal(canShip(mon859am), false);

    // Monday at 9 AM - should allow
    const mon9am = new Date('2026-11-23T09:00:00Z');
    assert.equal(canShip(mon9am), true);
  });

  it('blocks deploys after 6 PM', () => {
    // Tuesday at 5:59 PM - should allow
    const tue559pm = new Date('2026-11-17T17:59:00Z');
    assert.equal(canShip(tue559pm), true);

    // Tuesday at 6 PM - should block
    const tue6pm = new Date('2026-11-17T18:00:00Z');
    assert.equal(canShip(tue6pm), false);

    // Wednesday at 10 PM - should block
    const wed10pm = new Date('2026-11-18T22:00:00Z');
    assert.equal(canShip(wed10pm), false);
  });
});

